322	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
323	    @Override
324	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
325	        HttpHeaders headers = new HttpHeaders();
326	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
327	        String telephone = toE164(owner.getTelephone());
328	        if (telephone == null) {
329	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
330	        }
331	        if (!normalizeEmail(owner)) {
332	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
333	        }
334	        String address = normalizeAddress(owner.getAddress());
335	        if (address.isEmpty()) {
336	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
337	        }
338	        owner.setAddress(address);
339	        java.time.LocalDate registrationDate = toBusinessDay(
340	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
341	        if (ownersRegisteredOn(registrationDate) >= DAILY_CREATE_LIMIT) {
342	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
343	        }
344	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
345	            return new ResponseEntity<>(HttpStatus.CONFLICT);
346	        }
347	        for (Owner existing : this.clinicService.findAllOwners()) {
348	            String existingTelephone = toE164(existing.getTelephone());
349	            if (telephone.equals(existingTelephone)) {
350	                return new ResponseEntity<>(HttpStatus.CONFLICT);
351	            }
352	        }
353	        List<Owner> householdMembers = householdMembers(owner);
354	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
355	        if (!sharesHousehold && !householdMembers.isEmpty()) {
356	            return new ResponseEntity<>(HttpStatus.CONFLICT);
357	        }
358	        if (sharesHousehold && !householdMembers.isEmpty()) {
359	            String householdId = householdMembers.stream()
360	                .map(Owner::getHouseholdId)
361	                .filter(id -> id != null && !id.isBlank())
362	                .findFirst()
363	                .orElseGet(() -> householdIdFor(owner));
364	            owner.setHouseholdId(householdId);
365	            for (Owner member : householdMembers) {
366	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
367	                    member.setHouseholdId(householdId);
368	                    this.clinicService.saveOwner(member);
369	                }
370	            }
371	        }
372	        owner.setNamesakeCount(namesakeCount(owner));
373	        owner.setTelephone(telephone);
374	        owner.setRegistrationDate(registrationDate);
375	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
376	        this.clinicService.saveOwner(owner);
377	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
378	        headers.setLocation(UriComponentsBuilder.newInstance()
379	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
380	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
381	    }
