415	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
416	    @Override
417	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
418	        Owner owner = this.clinicService.findOwnerById(ownerId);
419	        if (owner == null) {
420	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
421	        }
422	        HttpHeaders headers = new HttpHeaders();
423	        Pet pet = petMapper.toPet(petFieldsDto);
424	        owner.setId(ownerId);
425	        pet.setOwner(owner);
426	        pet.getType().setName(null);
427	        this.clinicService.savePet(pet);
428	        PetDto petDto = petMapper.toPetDto(pet);
429	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
430	            .buildAndExpand(pet.getId()).toUri());
431	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
432	    }
