434	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
435	    @Override
436	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
437	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
438	        if (currentOwner != null) {
439	            Pet currentPet = this.clinicService.findPetById(petId);
440	            if (currentPet != null) {
441	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
442	                currentPet.setName(petFieldsDto.getName());
443	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
444	                this.clinicService.savePet(currentPet);
445	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
446	            }
447	        }
448	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
449	    }
